#!/usr/bin/env node
// Generated by harness-init — do not hand-edit; regenerate via render
//
// change-risk-gate.mjs  (TS/JS stack, harness-init 4.1.0)
//
// Folds a function's test coverage and its cyclomatic complexity into the clean-code
// CRAP metric, then reports function-level CRAP for a JS/TS codebase. A low-coverage,
// high-complexity function scores badly; full coverage collapses the score to the
// function's complexity.
//
//   crap = complexity**2 * (1 - coverage)**3 + complexity
//   FAIL when crap > ceiling + 1e-9 (score == ceiling is the allowed worst case)
//
// This is the reference formula from scripts/crap_checker.py (harness-init reference
// implementation) — the constant is duplicated per stack so every stack stays aligned.
//
// CLI (four-stack contract):
//   change-risk-gate.mjs --coverage <file> --ceiling <float> [--src <path>] [--json]
//
//   --coverage  istanbul JSON (nyc --reporter=json / vitest coverage-final.json).
//               Must exist; a missing file is exit 3 (no coverage data = red).
//   --ceiling   Q1.4 profile-derived ceiling (general=15.76, strict=10.0). Rendered by
//               harness-init; this script never picks a profile, it only labels known ones.
//   --src       source root (default ".").
//   --json      machine-readable JSON on stdout; the human report is sent to stderr.
//
// Exit codes: 0 all pass; 1 any function with CRAP > ceiling; 2 usage/argument error;
//             3 coverage data missing or unreadable.
//
// Notes / scope:
//   * The `typescript` parser handles .ts/.tsx/.js/.jsx/.mjs/.cjs (acorn cannot parse TS).
//   * Functions analysed = top-level function declarations, `export`ed declarations,
//     top-level variable-arrow/function assignments, and class methods (MethodDefinition).
//   * Coverage aggregation reads the istanbul `data.<path>.lines` map `{line: hitCount}`.
//     A line absent from the map counts as unexecuted (conservative / red) and marks the
//     function `[cov-unknown]`.

import fs from 'node:fs'
import path from 'node:path'

const EPSILON = 1e-9 // allowed worst case includes the ceiling; only score > ceiling + EPSILON fails

// Known Q1.4 derived ceilings (C + C^2 * (1 - p)^3). Display label only — this script
// does not select a profile; the profile/ceiling is chosen by the render step.
const KNOWN_CEILING_LABELS = {
  15.76: '一般配置',
  10.0: '严格配置',
}

// ----- Reference CRAP formula (matches scripts/crap_checker.py) -------------------

function crapScore(complexity, coverage) {
  return complexity ** 2 * (1 - coverage) ** 3 + complexity
}

function verdictOf(score, ceiling) {
  return score <= ceiling + EPSILON ? 'PASS' : 'FAIL'
}

function isValidCoverage(c) {
  return typeof c === 'number' && c >= 0 && c <= 1
}

// ----- Cyclomatic complexity via a hand-rolled McCabe walker ----------------------
// ts-estree emits ESTree nodes; we walk the tree ourselves over `type`-tagged children.

const COMPLEXITY_NODES = new Set([
  'IfStatement',
  'ForStatement',
  'ForOfStatement',
  'ForInStatement',
  'WhileStatement',
  'DoWhileStatement',
  'CatchClause',
  'SwitchStatement',
  'SwitchCase',
])

// A generic recursive walker: visits every child node reachable from `node`.
function walk(node, visit) {
  visit(node)
  for (const key of Object.keys(node)) {
    if (key === 'loc' || key === 'start' || key === 'end' || key === 'range' || key === 'parent') {
      continue
    }
    const value = node[key]
    if (Array.isArray(value)) {
      for (const el of value) {
        if (el && typeof el === 'object' && typeof el.type === 'string') {
          walk(el, visit)
        }
      }
    } else if (value && typeof value === 'object' && typeof value.type === 'string') {
      walk(value, visit)
    }
  }
}

function normalizeFn(fn) {
  // MethodDefinition carries nested nodes; the function body lives on `.value`.
  return fn.type === 'MethodDefinition' ? fn.value : fn
}

function computeComplexity(fn) {
  let points = 0
  walk(fn, (n) => {
    if (COMPLEXITY_NODES.has(n.type)) {
      points += 1
    } else if (n.type === 'LogicalExpression' && (n.operator === '&&' || n.operator === '||')) {
      points += 1
    }
  })
  return points + 1
}

function getBody(fn) {
  return fn.body
}

// Collect distinct statement start-lines inside a function body. The outer block's
// `{` line and empty statements are ignored so coverage is not dragged down by braces.
function collectBodyLines(body) {
  const lines = new Set()
  if (!body) {
    return lines
  }
  walk(body, (n) => {
    if (n.type === 'BlockStatement' || n.type === 'EmptyStatement') {
      return
    }
    if (n.loc && n.loc.start && typeof n.loc.start.line === 'number') {
      lines.add(n.loc.start.line)
    }
  })
  return lines
}

function collectFunctions(ast) {
  const found = []
  function add(fnNode, name, line) {
    found.push({ fn: fnNode, name, line })
  }

  function addClass(classNode) {
    for (const member of classNode.body.body) {
      if (member.type === 'MethodDefinition') {
        const key = member.key
        const name =
          key.type === 'Identifier'
            ? key.name
            : key.type === 'PrivateIdentifier'
              ? key.name
              : key.value !== undefined
                ? String(key.value)
                : 'anonymous'
        add(member, name, member.loc.start.line)
      }
    }
  }

  for (const stmt of ast.body) {
    if (stmt.type === 'FunctionDeclaration') {
      add(stmt, stmt.id ? stmt.id.name : 'anonymous', stmt.loc.start.line)
    } else if (stmt.type === 'ExportNamedDeclaration' && stmt.declaration) {
      const d = stmt.declaration
      if (d.type === 'FunctionDeclaration') {
        add(d, d.id ? d.id.name : 'anonymous', d.loc.start.line)
      } else if (d.type === 'VariableDeclaration') {
        for (const dec of d.declarations) {
          if (
            dec.init &&
            (dec.init.type === 'ArrowFunctionExpression' || dec.init.type === 'FunctionExpression')
          ) {
            add(
              dec.init,
              dec.id && dec.id.name ? dec.id.name : 'anonymous',
              dec.init.loc.start.line,
            )
          }
        }
      } else if (d.type === 'ClassDeclaration') {
        addClass(d)
      }
    } else if (stmt.type === 'ExportDefaultDeclaration' && stmt.declaration) {
      const d = stmt.declaration
      if (d.type === 'FunctionDeclaration') {
        add(d, d.id ? d.id.name : 'default', d.loc.start.line)
      } else if (d.type === 'ArrowFunctionExpression' || d.type === 'FunctionExpression') {
        add(d, 'default', d.loc.start.line)
      } else if (d.type === 'ClassDeclaration') {
        addClass(d)
      }
    } else if (stmt.type === 'VariableDeclaration') {
      for (const dec of stmt.declarations) {
        if (
          dec.init &&
          (dec.init.type === 'ArrowFunctionExpression' || dec.init.type === 'FunctionExpression')
        ) {
          add(dec.init, dec.id && dec.id.name ? dec.id.name : 'anonymous', dec.init.loc.start.line)
        }
      }
    } else if (stmt.type === 'ClassDeclaration' || stmt.type === 'ClassExpression') {
      addClass(stmt)
    }
  }
  return found
}

// ----- Coverage (istanbul JSON) --------------------------------------------------

const SOURCE_EXTENSIONS = new Set(['.ts', '.tsx', '.js', '.jsx', '.mjs', '.cjs'])
const IGNORED_DIRS = new Set([
  'node_modules',
  '.git',
  'dist',
  'build',
  'coverage',
  '.nyc_output',
  '__pycache__',
  '.next',
  '.cache',
  'out',
])

function collectSourceFiles(target) {
  const stat = fs.statSync(target)
  if (stat.isFile()) {
    return [target]
  }
  const results = []
  const stack = [target]
  while (stack.length) {
    const dir = stack.pop()
    let entries
    try {
      entries = fs.readdirSync(dir, { withFileTypes: true })
    } catch {
      continue
    }
    for (const ent of entries) {
      const full = path.join(dir, ent.name)
      if (ent.isDirectory()) {
        if (!IGNORED_DIRS.has(ent.name)) {
          stack.push(full)
        }
      } else if (ent.isFile() && SOURCE_EXTENSIONS.has(path.extname(ent.name).toLowerCase())) {
        results.push(full)
      }
    }
  }
  return results.sort()
}

function normalizeSlash(p) {
  return p.split(path.sep).join('/')
}

// Match an absolute source path against a key in the istanbul coverage map.
// Istanbul keys may be absolute, repo-relative (with/without leading ./), or basename.
function findCoverageMap(coverage, file, srcRoot) {
  const abs = normalizeSlash(path.resolve(file))
  const rel = normalizeSlash(path.relative(srcRoot, path.resolve(file)))
  const base = path.basename(file)
  const keys = Object.keys(coverage)

  for (const key of keys) {
    const k = normalizeSlash(String(key))
    if (k === abs || k === rel || k === base) {
      return coverage[key]
    }
  }
  for (const key of keys) {
    const k = normalizeSlash(String(key)).replace(/\/+$/, '')
    if (k.endsWith('/' + rel) || k.endsWith('/' + base)) {
      return coverage[key]
    }
  }
  return null
}

// Aggregate function-level line coverage from an istanbul `lines` map.
// Body lines missing from the map count as unexecuted (conservative / red) and the
// function is marked [cov-unknown].
function computeCoverage(bodyLines, linesMap) {
  if (bodyLines.size === 0) {
    return { coverage: 1.0, covUnknown: false }
  }
  let executed = 0
  let covUnknown = false
  for (const line of bodyLines) {
    const key = String(line)
    if (!linesMap || !Object.prototype.hasOwnProperty.call(linesMap, key)) {
      covUnknown = true // missing -> 0 hits -> not executed
      continue
    }
    const hits = linesMap[key]
    if (typeof hits === 'number' && hits > 0) {
      executed += 1
    }
  }
  return { coverage: executed / bodyLines.size, covUnknown }
}

// ----- Argument parsing -----------------------------------------------------------

function usage() {
  return [
    'usage: change-risk-gate.mjs --coverage <file> --ceiling <float> [--src <path>] [--json]',
    '  --coverage  istanbul JSON coverage file (must exist)',
    '  --ceiling   CRAP ceiling (Q1.4 profile value, e.g. 15.76 or 10.0)',
    '  --src       source root to scan (default ".")',
    '  --json      emit JSON on stdout; human report goes to stderr',
  ].join('\n')
}

function usageError(msg) {
  process.stderr.write(`change-risk-gate: ${msg}\n${usage()}\n`)
  return 2
}

function parseArgs(argv) {
  const args = { coverage: null, ceiling: NaN, src: '.', json: false, help: false }
  for (let i = 0; i < argv.length; i += 1) {
    const token = argv[i]
    if (token === '--coverage') {
      if (i + 1 >= argv.length) throw new Error('--coverage requires a value')
      args.coverage = argv[++i]
    } else if (token === '--ceiling') {
      if (i + 1 >= argv.length) throw new Error('--ceiling requires a value')
      args.ceiling = Number(argv[++i])
    } else if (token === '--src') {
      if (i + 1 >= argv.length) throw new Error('--src requires a value')
      args.src = argv[++i]
    } else if (token === '--json') {
      args.json = true
    } else if (token === '--help' || token === '-h') {
      args.help = true
    } else {
      throw new Error(`unknown argument: ${token}`)
    }
  }
  return args
}

// ----- Report --------------------------------------------------------------------

function fmtRow(e, ceiling) {
  const covPct = `${(e.coverage * 100).toFixed(1)}%`
  const name = e.name + (e.covUnknown ? '  [cov-unknown]' : '')
  const line = String(e.line).padStart(5)
  const complexity = String(e.complexity).padStart(11)
  const coverage = covPct.padStart(9)
  const score = e.score.toFixed(1).padStart(8)
  const verdict = verdictOf(e.score, ceiling).padStart(7)
  return `  ${line}  ${complexity}  ${coverage}  ${score}  ${verdict}  ${name}`
}

function fmtHeader() {
  return (
    '  ' +
    'line'.padStart(5) +
    '  ' +
    'complexity'.padStart(11) +
    '  ' +
    'coverage'.padStart(9) +
    '  ' +
    'score'.padStart(8) +
    '  ' +
    'verdict'.padStart(7) +
    '  function'
  )
}

function ceilingLabel(ceiling) {
  return KNOWN_CEILING_LABELS[ceiling] ? ` (${KNOWN_CEILING_LABELS[ceiling]})` : ''
}

function buildHuman(ceiling, entries, failed) {
  const out = [
    `change-risk-gate: ceiling=${ceiling.toFixed(2)}${ceilingLabel(ceiling)}`,
    fmtHeader(),
  ]
  for (const e of entries) {
    out.push(fmtRow(e, ceiling))
  }
  if (failed.length) {
    const names = failed
      .map((e) => `${e.name} (score ${e.score.toFixed(1)} > ${ceiling.toFixed(2)})`)
      .join(', ')
    out.push(`FAIL ${failed.length} function(s) above ceiling: ${names}`)
  } else {
    out.push(`PASS: all ${entries.length} function(s) at or below ceiling=${ceiling.toFixed(2)}`)
  }
  return out.join('\n')
}

function buildJson(ceiling, entries, failed) {
  return {
    ceiling,
    results: entries.map((e) => ({
      function: e.name,
      line: e.line,
      complexity: e.complexity,
      coverage: Number(e.coverage.toFixed(4)),
      score: Number(e.score.toFixed(2)),
      verdict: verdictOf(e.score, ceiling),
      ...(e.covUnknown ? { covUnknown: true } : {}),
    })),
    failed: failed.length,
    total: entries.length,
  }
}

// ----- Main ----------------------------------------------------------------------

function main() {
  let args
  try {
    args = parseArgs(process.argv.slice(2))
  } catch (err) {
    process.exitCode = usageError(err.message)
    return
  }

  if (args.help) {
    process.stdout.write(`${usage()}\n`)
    process.exitCode = 0
    return
  }

  if (args.coverage == null) {
    process.exitCode = usageError('missing --coverage <file>')
    return
  }
  if (!Number.isFinite(args.ceiling)) {
    process.exitCode = usageError('missing or invalid --ceiling <float>')
    return
  }
  if (!fs.existsSync(args.coverage)) {
    process.stderr.write(
      `change-risk-gate: coverage file not found: ${args.coverage}\n` +
        '  Run your test suite first to produce coverage (e.g. `nyc --reporter=json` ' +
        'or `vitest run --coverage`).\n',
    )
    process.exitCode = 3
    return
  }
  if (!fs.existsSync(args.src)) {
    process.exitCode = usageError(`source root not found: ${args.src}`)
    return
  }

  let coverage
  try {
    coverage = JSON.parse(fs.readFileSync(args.coverage, 'utf8'))
  } catch (err) {
    process.stderr.write(
      `change-risk-gate: cannot parse coverage file ${args.coverage}: ${err.message}\n`,
    )
    process.exitCode = 3
    return
  }
  if (!coverage || typeof coverage !== 'object') {
    process.stderr.write(
      `change-risk-gate: coverage file ${args.coverage} is not an istanbul JSON object\n`,
    )
    process.exitCode = 3
    return
  }

  const sourceFiles = collectSourceFiles(args.src)
  if (sourceFiles.length === 0) {
    process.stderr.write(
      `change-risk-gate: no source files (.ts/.tsx/.js/.jsx/.mjs/.cjs) found under ${args.src}\n`,
    )
    process.exitCode = 2
    return
  }

  const srcRoot = fs.statSync(args.src).isDirectory() ? args.src : path.dirname(args.src)
  const entries = []

  for (const file of sourceFiles) {
    let source
    try {
      source = fs.readFileSync(file, 'utf8')
    } catch (err) {
      process.stderr.write(`change-risk-gate: cannot read ${file}: ${err.message}\n`)
      continue
    }
    let ast
    try {
      // .tsx/.jsx parse as JSX; .ts/.js do NOT — estree with jsx:true misreads
      // `shallowRef<Error | undefined>(...)` generics as JSX children.
      const jsx = /\.(tsx|jsx)$/.test(file)
      ast = parse(source, { loc: true, range: true, jsx, comment: false, tokens: false })
    } catch (scriptErr) {
      process.stderr.write(`change-risk-gate: skipping unparseable ${file}: ${scriptErr.message}\n`)
      continue
    }

    const linesMap = findCoverageMap(coverage, file, srcRoot)?.lines ?? null
    const funcs = collectFunctions(ast)
    for (const f of funcs) {
      const fn = normalizeFn(f.fn)
      const complexity = computeComplexity(fn)
      const bodyLines = collectBodyLines(getBody(fn))
      const cov = computeCoverage(bodyLines, linesMap)
      if (!isValidCoverage(cov.coverage)) {
        continue // defensive: never feed an out-of-range coverage into the formula
      }
      entries.push({
        name: f.name,
        line: f.line,
        complexity,
        coverage: cov.coverage,
        covUnknown: cov.covUnknown,
        score: crapScore(complexity, cov.coverage),
      })
    }
  }

  if (entries.length === 0) {
    process.stderr.write(`change-risk-gate: no functions found under ${args.src}\n`)
    process.stderr.write(
      'change-risk-gate: error: an empty gate would pass silently; check --src/--exclude\n',
    )
    process.exitCode = 2
    return
  }

  entries.sort((a, b) => b.score - a.score)
  const failed = entries.filter((e) => e.score > args.ceiling + EPSILON)

  const human = buildHuman(args.ceiling, entries, failed)
  if (args.json) {
    process.stderr.write(`${human}\n`)
    process.stdout.write(`${JSON.stringify(buildJson(args.ceiling, entries, failed))}\n`)
  } else {
    process.stdout.write(`${human}\n`)
  }

  process.exitCode = failed.length ? 1 : 0
}

// typescript is a devDependency (the standard TS parser — acorn cannot parse TS
// type annotations or interface declarations); a missing module is a
// coverage-setup problem (exit 3), not a usage error.
// @typescript-eslint/typescript-estree is the devDependency — it parses
// .ts/.tsx/.js/.jsx/.mjs/.cjs (including type annotations) into ESTree nodes.
// A missing module is a coverage-setup problem (exit 3), not a usage error.
import { createRequire } from 'module'
const tsRequire = createRequire(import.meta.url)
let parse
try {
  ;({ parse } = tsRequire('@typescript-eslint/typescript-estree'))
} catch (err) {
  process.stderr.write(
    'change-risk-gate: the `@typescript-eslint/typescript-estree` parser is required.\n' +
      '  Install it as a dev dependency:  npm i -D @typescript-eslint/typescript-estree\n',
  )
  process.exit(3)
}

main()
